import React from "react";
import {PiCardProps} from "@pihanga2/core";
import {FileUploader} from "react-drag-drop-files";
import {
  DEF_FILE_DROP_FILE_TYPES,
  FileDropEvents,
  FileDropProps,
} from "./fileDrop.types";
import "./fileDrop.css";

type LastDropped = {name: string; file: File};

const KEY = Symbol.for("pihanga.card.FileDrop.LastDropped");

const globalForCache = globalThis as unknown as Record<
  symbol,
  LastDropped | null | undefined
>;

export function get_last_dropped(name: string): File | null {
  const slot = (globalForCache[KEY] ??= null);
  if (slot?.name === name) {
    return slot.file;
  }
  return null;
}

function setLastDropped(value: LastDropped): void {
  globalForCache[KEY] = value;
}

function clearLastDropped(): void {
  globalForCache[KEY] = null;
}

export const FileDropComponent = (
  props: PiCardProps<FileDropProps, FileDropEvents>,
): React.ReactNode => {
  const {
    fileTypes = DEF_FILE_DROP_FILE_TYPES,
    title = "Click or drop a file right here",
    description,
    showProgress = false,
    progress = 0,
    progressStyle = {},
    dropStyle = {},
    onFileDropped,
    onError,
    cardName,
    className,
    _cls,
  } = props;

  function handleChange(file: File | File[]): void {
    const f = Array.isArray(file) ? file[0] : file;
    if (!f) return;
    const {name, size, type} = f;
    setLastDropped({name, file: f});
    onFileDropped({name, size, type});
    // clean up reference to File in a few sec to avoid dangling reference
    setTimeout(clearLastDropped, 2000);
  }

  function handleTypeError(err: unknown): void {
    onError({error: String(err)});
  }

  function renderProgress(): React.ReactNode {
    const label = `${progress}%`;
    const msg = `${label} Complete`;
    const containerStyle = {width: "50%", ...progressStyle};
    return (
      <div className="pi-progress">
        <div className="pi-progress-label">{label}</div>
        <div
          className="pi-progress-container"
          style={containerStyle as React.CSSProperties}
        >
          <div
            className="pi-progress-bar"
            style={{width: label}}
            role="progressbar"
            aria-label={msg}
          />
        </div>
      </div>
    );
  }

  function renderDropZone(): React.ReactElement {
    return (
      <div className="dropzone-msg" style={dropStyle as React.CSSProperties}>
        {title && <h3 className="dropzone-msg-title">{title}</h3>}
        {description && (
          <span className="dropzone-msg-desc">{description}</span>
        )}
      </div>
    );
  }

  function renderFileUploader(): React.ReactNode {
    return (
      <FileUploader
        handleChange={handleChange}
        onTypeError={handleTypeError}
        name="file"
        types={fileTypes}
        hoverTitle=" "
      >
        {renderDropZone()}
      </FileUploader>
    );
  }

  const cn = _cls("root", className);
  return (
    <div className={cn} data-pihanga={cardName}>
      {showProgress ? renderProgress() : renderFileUploader()}
    </div>
  );
};

.pi-file-drop-root label {
  /* background-color: yellow; */
  max-width: 100%;
  border: dashed 2px #999;
  /* #666; */

  display: flex;
  justify-content: space-between;
  flex-grow: 1;
}

.pi-file-drop-root .dropzone-msg {
  cursor: pointer;
  text-align: center;
  margin: 3em 0;
  flex-grow: 4;
}

/*** PROGRESS ***/

.pi-file-drop-root .pi-progress {
  /* background-color: yellow; */
  max-width: 100%;

  /* display: flex; */
  /* flex: 1 1 auto; */
  padding: 1.25em;

}

.pi-file-drop-root .pi-progress-label {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.5rem;
}

.pi-file-drop -root.pi-progress-container {
  position: relative;
  display: flex;
  height: 1rem;
  overflow: hidden;
  border-radius: 4px;
  background-color: #dadfe5;
}

.pi-file-drop-root .pi-progress-bar {
  background-color: #0054a6;
  color: #ffffff;
  display: flex;
  flex-direction: column;
  justify-content: center;
  overflow: hidden;
}

.pi-file-drop-root .pi-progress .label {
  font-size: 1em;
  display: block;
}

import {
  createCardDeclaration,
  createOnAction,
  registerActions,
} from "@pihanga2/core";

export const FILE_DROP_CARD = "shad/file-drop";

export const FileDrop = createCardDeclaration<FileDropProps, FileDropEvents>(
  FILE_DROP_CARD,
);

export const FILE_DROP_ACTION = registerActions(FILE_DROP_CARD, [
  "file_dropped",
  "error",
]);

export const onFileDropped = createOnAction<FileDroppedEvent>(
  FILE_DROP_ACTION.FILE_DROPPED,
);

export const onFileDropError = createOnAction<FileDropErrorEvent>(
  FILE_DROP_ACTION.ERROR,
);

export type FileDropProps<S = Record<string, unknown>> = {
  /** Accepted file extensions, e.g. ["JPG", "PNG", "PDF"]. Defaults to ["JPG", "PNG", "GIF"]. */
  fileTypes?: string[];
  /** Heading shown inside the drop zone. */
  title?: string;
  /** Secondary text shown inside the drop zone. */
  description?: string;
  /** When true, shows a progress bar instead of the drop zone. */
  showProgress?: boolean;
  /** Inline styles applied to the drop zone wrapper. */
  dropStyle?: Record<string, unknown>;
  /** Inline styles applied to the progress bar container. */
  progressStyle?: Record<string, unknown>;
  /** Current upload progress (0–100). Only used when `showProgress` is true. */
  progress?: number;

  style?: S;
  className?: string;
};

export const DEF_FILE_DROP_FILE_TYPES = ["JPG", "PNG", "GIF"];

export type FileDroppedEvent = {
  name: string;
  size: number;
  type: string;
};

export type FileDropErrorEvent = {
  error: string;
};

export type FileDropEvents = {
  onFileDropped: FileDroppedEvent;
  onError: FileDropErrorEvent;
};

import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {FileDropComponent} from "./fileDrop.component";
import {FILE_DROP_ACTION, FILE_DROP_CARD} from "./fileDrop.types";

export * from "./fileDrop.types";
export {get_last_dropped} from "./fileDrop.component";

registerCardComponent({
  name: FILE_DROP_CARD,
  component: FileDropComponent,
  events: actionTypesToEvents(FILE_DROP_ACTION),
});
